# Export thinned, lightly smoothed morph-span landmark tracks as a JS module (measured motion only, no pixels).
import json, numpy as np, sys
d=json.load(open('spans.json'))
out=["// Landmark tracks for the designer morph, measured on the source with pyramidal Lucas-Kanade (forward/backward",
     "// checked), one row per frame (0.04 s) from the span start to its end; each row = x0,y0,x1,y1,... (frame px).",
     "// Generated by snapshots/s04-study/export_tracks.py — numbers only.","export const SPANS = {"]
for key,T in d.items():
    T=np.array(T)  # frames x N x 2
    # smooth interior frames
    S=T.copy()
    if T.shape[0]>2: S[1:-1]=0.25*T[:-2]+0.5*T[1:-1]+0.25*T[2:]
    # thin: min spacing at the start frame and the end frame
    keep=[]
    order=np.argsort(np.random.RandomState(1).rand(S.shape[1]))
    for j in order:
        a,b=S[0,j],S[-1,j]
        if all(np.hypot(*(a-S[0,k]))>38 and np.hypot(*(b-S[-1,k]))>30 for k in keep): keep.append(j)
    S=S[:,sorted(keep)]
    a,b=[float(x) for x in key.split('-')]
    rows=",\n    ".join("["+",".join(str(int(round(v))) for v in S[f].ravel())+"]" for f in range(S.shape[0]))
    out.append(f'  "{key}": {{ t0: {a}, t1: {b}, n: {S.shape[1]}, rows: [\n    {rows}] }},')
    print(key,S.shape, file=sys.stderr)
out.append("};")
open(sys.argv[1],'w').write("\n".join(out)+"\n")
